<?php require_once __DIR__ . '/includes/toast.php'; ?>
<script>
(function(){'use strict';
var api='api/business-profile.php',previewApi='api/business-profile-preview.php',csrf=<?=json_encode($csrfToken)?>,previewUrl='',lastDocType='quote',previewTimer=null,selectedLogoFile=null;
function E(id){return document.getElementById(id)}
function toast(t,m){if(window.fieldplxToast)window.fieldplxToast(t,m);else alert(m)}
function postForm(form,extra){var fd=new FormData(form);if(extra)Object.keys(extra).forEach(function(k){fd.set(k,extra[k]);});return fetch(api,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(raw){var d;try{d=JSON.parse(raw)}catch(e){throw new Error(raw.replace(/<[^>]+>/g,' ').trim()||'Invalid server response.')}if(!r.ok||!d.success)throw new Error(d.message||'Unable to save.');return d;});});}
function closeModals(){document.querySelectorAll('.bp-modal-bg').forEach(function(m){m.classList.remove('open');});document.body.style.overflow='';closeFieldPops();}
document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModals)});document.querySelectorAll('.bp-modal-bg').forEach(function(m){m.addEventListener('mousedown',function(e){if(e.target===m)closeModals();});});document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeModals();closeMobileSettings();}});
function openModal(m){m.classList.add('open');document.body.style.overflow='hidden'}
document.querySelectorAll('.ajax-form').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();var btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;postForm(form).then(function(d){toast('success',d.message);if(form.dataset.formType==='save_brand_colors')form.querySelectorAll('input[type=color]').forEach(function(i){var s=i.closest('.color-row').querySelector('.color-meta span');if(s)s.textContent=i.value.toUpperCase();});if(form.dataset.formType==='save_document_settings'){schedulePreview();refreshDocumentCard();}}).catch(function(err){toast('error',err.message)}).finally(function(){if(btn)btn.disabled=false;});});});
document.querySelectorAll('[data-reset-form]').forEach(function(b){b.onclick=function(){b.closest('form').reset()}});document.querySelectorAll('.countable').forEach(function(t){t.oninput=function(){var c=t.parentNode.querySelector('.bp-count span');if(c)c.textContent=t.value.length}});document.querySelectorAll('.bp-accordion-btn').forEach(function(b){b.onclick=function(){var s=b.nextElementSibling,open=s.style.display!=='none';s.style.display=open?'none':'block';b.lastElementChild.textContent=open?'⌄':'⌃'}});
var consent=E('aiConsent'),gen=E('generateAiBtn');if(consent&&gen){consent.onchange=function(){gen.disabled=!consent.checked};gen.onclick=function(){toast('warning','AI content generation requires your configured AI service.')}}
var legalModal=E('legalModal'),legalTitle=E('legalTitle'),legalType=E('legalType'),legalUrl=E('legalUrl'),legalHelp=E('legalHelp'),legalValues={terms:<?=json_encode((string)$profile['terms_url'])?>,privacy:<?=json_encode((string)$profile['privacy_url'])?>};document.querySelectorAll('[data-legal]').forEach(function(b){b.onclick=function(){var type=b.dataset.legal;legalType.value=type;legalUrl.value=legalValues[type]||'';legalTitle.textContent=type==='terms'?'Edit Terms and Conditions':'Edit Privacy Policy';legalHelp.textContent=type==='terms'?'Add a link to the terms and conditions your customers agree to when they work with you.':'Add a link to your privacy policy so customers can see how you collect and use their information.';openModal(legalModal)}});E('legalForm').onsubmit=function(e){e.preventDefault();postForm(this).then(function(d){var type=legalType.value;legalValues[type]=legalUrl.value;E(type+'Status').textContent=legalUrl.value||('Add a link to your '+(type==='terms'?'terms and conditions.':'privacy policy.'));toast('success',d.message);closeModals()}).catch(function(err){toast('error',err.message)})};
/* Logo modal */
function resetLogoModal(){selectedLogoFile=null;E('logoInput').value='';E('logoPreviewArea').classList.remove('show');E('logoPreviewImage').removeAttribute('src');E('saveLogoBtn').disabled=true;E('logoDrop').classList.remove('drag')}
function openLogoModal(){resetLogoModal();openModal(E('logoModal'))}
document.addEventListener('click',function(e){var b=e.target.closest('[data-logo-action]');if(!b)return;var a=b.getAttribute('data-logo-action');if(a==='replace')openLogoModal();else if(a==='delete')deleteLogo();});
function acceptLogo(file){if(!file)return;if(['image/png','image/jpeg'].indexOf(file.type)<0){toast('warning','Logo must be PNG, JPG or JPEG.');return}if(file.size>5*1024*1024){toast('warning','Logo must be 5 MB or smaller.');return}selectedLogoFile=file;var r=new FileReader();r.onload=function(){E('logoPreviewImage').src=r.result;E('logoPreviewArea').classList.add('show');E('saveLogoBtn').disabled=false};r.readAsDataURL(file)}
E('logoInput').onchange=function(){acceptLogo(this.files&&this.files[0])};E('logoDrop').addEventListener('dragover',function(e){e.preventDefault();this.classList.add('drag')});E('logoDrop').addEventListener('dragleave',function(){this.classList.remove('drag')});E('logoDrop').addEventListener('drop',function(e){e.preventDefault();this.classList.remove('drag');acceptLogo(e.dataTransfer&&e.dataTransfer.files?e.dataTransfer.files[0]:null)});
E('saveLogoBtn').onclick=function(){if(!selectedLogoFile)return;var btn=this,fd=new FormData();fd.append('csrf_token',csrf);fd.append('action','upload_logo');fd.append('logo',selectedLogoFile,selectedLogoFile.name);btn.disabled=true;btn.textContent='Saving...';fetch(api,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json().then(function(d){if(!r.ok||!d.success)throw new Error(d.message||'Upload failed.');return d})}).then(function(d){E('logoBox').innerHTML='<img src="'+d.logo_path+'?v='+Date.now()+'" alt="Company logo"><div class="logo-card-actions"><button class="bp-btn bp-btn-danger" type="button" data-logo-action="delete">Delete</button><button class="bp-btn" type="button" data-logo-action="replace">Replace</button></div>';toast('success',d.message);closeModals();schedulePreview();refreshDocumentCard()}).catch(function(err){toast('error',err.message)}).finally(function(){btn.textContent='Save';btn.disabled=!selectedLogoFile})};
function deleteLogo(){if(!confirm('Delete this company logo?'))return;var fd=new FormData();fd.append('csrf_token',csrf);fd.append('action','remove_logo');fetch(api,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json().then(function(d){if(!r.ok||!d.success)throw new Error(d.message||'Unable to delete logo.');return d})}).then(function(d){E('logoBox').innerHTML='<div class="logo-empty">No company logo uploaded</div><button class="bp-btn" type="button" data-logo-action="replace">Add logo</button>';toast('success',d.message);schedulePreview();refreshDocumentCard()}).catch(function(err){toast('error',err.message)})}
/* Document settings */
var docModal=E('docModal'),frame=E('docPdfFrame'),loader=E('docPreviewLoading'),previewError=E('docPreviewError');E('openDocSettings').onclick=function(){openModal(docModal);setActiveTab('quote');schedulePreview(10)};
function activePane(){return document.querySelector('.doc-pane.active')}
function setActiveTab(type){document.querySelectorAll('.doc-tab').forEach(function(t){t.classList.toggle('active',t.dataset.docTab===type)});document.querySelectorAll('.doc-pane').forEach(function(p){p.classList.toggle('active',p.dataset.docPane===type)});if(type!=='style')lastDocType=type;updateFieldTriggers();schedulePreview(20)}
document.querySelectorAll('.doc-tab').forEach(function(tab){tab.onclick=function(){setActiveTab(tab.dataset.docTab)}});
var estimate=E('estimateToggle'),quoteLabel=E('quoteLabel');if(estimate)estimate.onchange=function(){quoteLabel.value=estimate.checked?'Estimate':'Quote';schedulePreview()};
document.querySelector('[data-reset-quote-message]').onclick=function(){var f=document.querySelector('[data-doc-pane="quote"]');f.querySelector('[name="contract_disclaimer"]').value='This quote is valid for the next 30 days, after which values may be subject to change.';f.querySelector('[name="deposit_language"]').value='A deposit of {{DEPOSIT_AMOUNT}} will be required to begin.';schedulePreview()};
function closeFieldPops(){document.querySelectorAll('.doc-field-pop.open').forEach(function(p){p.classList.remove('open')})}
document.querySelectorAll('.doc-field-trigger').forEach(function(btn){btn.onclick=function(e){e.stopPropagation();var pop=btn.nextElementSibling,was=pop.classList.contains('open');closeFieldPops();if(!was){pop.classList.add('open');var s=pop.querySelector('.doc-field-search');if(s)setTimeout(function(){s.focus()},20)}}});document.addEventListener('click',function(e){if(!e.target.closest('.doc-field-picker'))closeFieldPops()});
document.querySelectorAll('.doc-field-search').forEach(function(s){s.oninput=function(){var q=s.value.toLowerCase();s.closest('.doc-field-pop').querySelectorAll('.doc-field-option').forEach(function(o){o.style.display=o.dataset.fieldName.indexOf(q)>=0?'flex':'none'})}});document.querySelectorAll('[data-select-all]').forEach(function(b){b.onclick=function(){var pop=b.closest('.doc-field-pop'),boxes=pop.querySelectorAll('.doc-field-option input');var all=Array.prototype.every.call(boxes,function(x){return x.checked});boxes.forEach(function(x){x.checked=!all});updateFieldTriggers();schedulePreview()}});
function updateFieldTriggers(){document.querySelectorAll('.doc-field-picker').forEach(function(p){var checked=p.querySelectorAll('.doc-field-option input:checked'),btn=p.querySelector('.doc-field-trigger'),names=[];checked.forEach(function(x){var sp=x.closest('.doc-field-option').querySelector('span');if(sp)names.push(sp.textContent)});btn.textContent=names.length?('Custom fields selected | '+names.join(', ')):'Select fields to display  +';btn.title=btn.textContent})}
document.querySelectorAll('.doc-field-option input').forEach(function(x){x.onchange=function(){updateFieldTriggers();schedulePreview()}});updateFieldTriggers();
function appendForm(fd,form,prefix){Array.prototype.forEach.call(form.elements,function(el){if(!el.name||el.disabled||el.type==='submit'||el.type==='button')return;var name=el.name;if(name==='csrf_token'||name==='action'||name==='document_type')return;if(name==='selected_fields[]'){if(el.checked)fd.append(prefix+'selected_fields[]',el.value);return}if(el.type==='checkbox'){fd.append(prefix+name,el.checked?'1':'0');return}fd.append(prefix+name,el.value)})}
function buildPreviewData(){var fd=new FormData();fd.append('csrf_token',csrf);var active=activePane(),activeType=active?active.dataset.docPane:'quote',docType=activeType==='style'?lastDocType:activeType;fd.append('preview_type',docType);var docForm=document.querySelector('[data-doc-pane="'+docType+'"]'),styleForm=document.querySelector('[data-doc-pane="style"]');if(docForm)appendForm(fd,docForm,'doc_');if(styleForm)appendForm(fd,styleForm,'style_');return fd}
function schedulePreview(delay){clearTimeout(previewTimer);previewTimer=setTimeout(loadPreview,delay==null?320:delay)}
function loadPreview(){if(!docModal.classList.contains('open'))return;loader.classList.add('show');previewError.classList.remove('show');fetch(previewApi,{method:'POST',body:buildPreviewData(),credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/pdf'}}).then(function(r){if(!r.ok)return r.text().then(function(t){throw new Error(t||'Unable to create PDF preview.')});return r.blob()}).then(function(blob){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(blob);frame.src=previewUrl+'#page=1&zoom=page-width&toolbar=0&navpanes=0&scrollbar=0';loader.classList.remove('show')}).catch(function(err){loader.classList.remove('show');previewError.textContent=err.message;previewError.classList.add('show')})}
docModal.addEventListener('input',schedulePreview);docModal.addEventListener('change',schedulePreview);document.querySelectorAll('[data-preview-pdf]').forEach(function(b){b.onclick=function(){if(previewUrl)window.open(previewUrl,'_blank');else{loadPreview();toast('info','Generating PDF preview…')}}});
function refreshDocumentCard(){var f=document.querySelector('.bp-doc-thumb iframe');if(f)f.src='api/business-profile-preview.php?type=invoice&stored=1&v='+Date.now()+'#page=1&zoom=page-width&toolbar=0&navpanes=0&scrollbar=0'}
/* Mobile Settings navigation */
var mobileBtn=E('bpMobileSettingsBtn'),mobilePanel=E('bpMobileSettingsPanel'),mobileOverlay=E('bpMobileSettingsOverlay'),desktopNav=document.querySelector('.bp-layout > .fieldplx-settings-nav');if(desktopNav&&mobilePanel){var clone=desktopNav.cloneNode(true);mobilePanel.appendChild(clone)}
function openMobileSettings(){mobilePanel.classList.add('open');mobileOverlay.classList.add('open');mobileBtn.classList.add('open');document.body.style.overflow='hidden'}function closeMobileSettings(){mobilePanel.classList.remove('open');mobileOverlay.classList.remove('open');mobileBtn.classList.remove('open');if(!document.querySelector('.bp-modal-bg.open'))document.body.style.overflow=''}if(mobileBtn)mobileBtn.onclick=function(){mobilePanel.classList.contains('open')?closeMobileSettings():openMobileSettings()};if(mobileOverlay)mobileOverlay.onclick=closeMobileSettings;if(mobilePanel)mobilePanel.addEventListener('click',function(e){if(e.target.closest('a'))closeMobileSettings()});window.addEventListener('resize',function(){if(window.innerWidth>1050)closeMobileSettings()});
})();
</script>
